// Mail im IMAP-Ordner 'matter' (Postfach Netcup Automation). Der Body ist nur ein Platzhalter
// ('no body neeeded'); die eigentlichen Daten stecken in einem JSON-Anhang, den ein externes
// DLRG-Formular ('Gruppennachricht auf iPads') per Mail schickt:
// { formular, antwortId, eingereichtAm, absender, ipadAuswahl, nachricht }
// ipadAuswahl waehlt die iPad-Gruppe/den Ort -> wird hier auf den Mattermost-Channel im Team
// DLRG-Andernach gemappt. 'Allgemein' bedeutet alle Gruppen und geht an alle drei Channels.
const CHANNEL_IDS = {
  'vorstandstisch': 'oeh5bbsydjrq5dmcjpoqq1ws6c',
  'kleines-becken': '1483rsfj5pn8ugg4r5quubr4zh',
  'grosses-becken': '3nq3unnih3gftn3cqsd36inpco',
  'town-square': 'ckbitwbfgfgu9yamydikr9jneh',
};
const ZIEL_CHANNELS = {
  'Vorstandstisch': ['vorstandstisch'],
  'Kleines Becken': ['kleines-becken'],
  'Großesbecken': ['grosses-becken'],
  'Alle iPads': ['town-square'],
};

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binary = item.binary || {};
  const keys = Object.keys(binary);
  const isJson = (key) => binary[key].mimeType === 'application/json' || /\.json$/i.test(binary[key].fileName || '');
  const jsonKey = keys.find(isJson);
  if (!jsonKey) {
    throw new Error('Kein JSON-Anhang in der Mail "' + (item.json.subject || '(ohne Betreff)') + '" gefunden.');
  }

  const jsonText = (await this.helpers.getBinaryDataBuffer(i, jsonKey)).toString('utf8').replace(/^\uFEFF/, '').trim();
  let daten;
  try {
    daten = JSON.parse(jsonText);
  } catch (e) {
    throw new Error('JSON-Anhang ist nicht lesbar: ' + e.message);
  }

  const { ipadAuswahl, nachricht, absender, eingereichtAm } = daten;
  if (!ipadAuswahl || !nachricht) {
    throw new Error('Pflichtfelder fehlen (ipadAuswahl/nachricht): ' + JSON.stringify(daten));
  }

  const ziele = ZIEL_CHANNELS[ipadAuswahl];
  if (!ziele) {
    throw new Error('Unbekannte ipadAuswahl "' + ipadAuswahl + '". Bekannt: ' + Object.keys(ZIEL_CHANNELS).join(', '));
  }

  const zeit = eingereichtAm
    ? new Date(eingereichtAm).toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' })
    : '';
  const text = '#### \u{1F4F1} Nachricht an iPads \u2013 ' + ipadAuswahl + '\n\n' + nachricht
    + '\n\n_Absender: ' + (absender || 'unbekannt') + (zeit ? ' \u00b7 eingereicht am ' + zeit + ' Uhr' : '') + '_';

  for (const slug of ziele) {
    out.push({ json: { channelId: CHANNEL_IDS[slug], channelSlug: slug, message: text, ipadAuswahl } });
  }
}
return out;

// Wird ueber den Fehler-Ausgang von 'Nachricht aufbereiten' bzw. 'An Mattermost senden' erreicht.
// Die Mail ist zu diesem Zeitpunkt im Postfach schon als gelesen markiert.
const first = $input.first().json;
const err = first && first.error;
const reason = (typeof err === 'string' ? err : err && (err.message || err.description)) || JSON.stringify(first);
return [{ json: { body: 'Fehler beim Weiterleiten einer iPad-Gruppennachricht nach Mattermost: ' + reason
  + '\n\nDie Mail ist im Postfach (Ordner matter) bereits als gelesen markiert.' } }];
